	private static QueryPlanSnapshotBatchProcessRunner runner(Path directory,
			WorkerLauncher.WorkerProcess worker, Duration hardTimeout) {
		return new QueryPlanSnapshotBatchProcessRunner(
				(arguments, stdoutPath, stderrPath) -> worker,
				hardTimeout,
				Duration.ofMillis(10),
				directory.resolve("audit.csv"),
				directory.resolve("workers"),
				new PrintStream(new ByteArrayOutputStream(), true, StandardCharsets.UTF_8));
	}

	private static QueryPlanSnapshotBatchProcessRunner.WorkerTarget target(String queryId, int queryIndex) {
		return new QueryPlanSnapshotBatchProcessRunner.WorkerTarget(queryId, "MEDICAL_RECORDS", queryIndex,
				List.of("--help"));
	}

	private static void assertAudit(Path directory, int rowIndex, String queryId, String status, String phase,
			String termination, String exitCode) throws Exception {
		List<String> lines = Files.readAllLines(directory.resolve("audit.csv"), StandardCharsets.UTF_8);
		List<String> values = parseCsvLine(lines.get(rowIndex));
		assertEquals(queryId, values.get(0), lines.toString());
		assertEquals(status, values.get(3), lines.toString());
		assertEquals(phase, values.get(4), lines.toString());
		assertEquals(termination, values.get(5), lines.toString());
		assertEquals(exitCode, values.get(6), lines.toString());
	}

	private static List<String> parseCsvLine(String line) {
		List<String> values = new ArrayList<>();
		StringBuilder current = new StringBuilder();
		boolean quoted = false;
		for (int index = 0; index < line.length(); index++) {
			char character = line.charAt(index);
			if (character == '"') {
				if (quoted && index + 1 < line.length() && line.charAt(index + 1) == '"') {
					current.append('"');
					index++;
				} else {
					quoted = !quoted;
				}
			} else if (character == ',' && !quoted) {
				values.add(current.toString());
				current.setLength(0);
			} else {
				current.append(character);
			}
		}
		values.add(current.toString());
		return values;
	}

